            <circle cx="110" cy="110" r="100" fill="rgba(255,255,255,0.02)"/>
            <g>
              <path class="note" data-note="bergamot" d="M110 10 L170 70 A100 100 0 0 1 110 110 Z" fill="#FFDCA8"/>
              <path class="note" data-note="lavender" d="M110 10 L50 70 A100 100 0 0 1 110 110 Z" fill="#D7C7FF"/>
