  <script>
    // Populate based on query params (prefill)
    const params = new URLSearchParams(location.search);
    if(params.get('plan')){
      document.getElementById('presetPlan').value = params.get('plan');
    }
    if(params.get('mood')){
      // highlight mood
      const mood = params.get('mood');
      const btn = Array.from(document.querySelectorAll('#bookMood button')).find(b=>b.dataset.mood===mood);
      if(btn) btn.classList.add('active');
      updateBookingCta(mood);
    }

    // Mood mapping for bookings
    const moodMap = {
      calm:{label:'Book Calm Moment',plan:'Moment Tending'},
      focus:{label:'Book Focus Session',plan:'Pocket Series — 3'},
      sleep:{label:'Book Wind-down',plan:'Anchor Session'},
      energize:{label:'Book Energize Mini',plan:'Moment Tending'},
      ground:{label:'Book Grounding Support',plan:'Anchor Session'}
    };

    function updateBookingCta(mood){
      const map = moodMap[mood];
      const submit = document.getElementById('submitBtn');
      const direct = document.getElementById('directCta');
      if(map){
        submit.textContent = map.label;
        direct.textContent = map.label;
        document.getElementById('presetPlan').value = map.plan;
        // attach mood to CTA link
        const u = new URL('{{PRIMARY_CTA_URL}}', location.href);
        u.searchParams.set('mood', mood);
        direct.href = u.toString();
      }
    }

    // Mood selection buttons
    document.querySelectorAll('#bookMood button').forEach(b=>{
      b.addEventListener('click',()=>{
        document.querySelectorAll('#bookMood button').forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        const mood = b.dataset.mood;
        updateBookingCta(mood);
      });
    });

    // Time slot toggles
    document.querySelectorAll('#timeSlots button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#timeSlots button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));

    // Aroma slice hovers in aside
    const asideNotes = document.querySelectorAll('svg .note');
    const asideInfo = document.getElementById('asideNote');
    const noteText = {bergamot:'Top note: bright citrus. Avoid undiluted skin contact and watch for phototoxic oils.',lavender:'Middle note: floral and calming; dilute for skin use.',vetiver:'Base note: earthy and grounding; suggest lower dilution near sleep.'};
    asideNotes.forEach(n=>{
      n.addEventListener('mouseenter',()=>{asideInfo.textContent = noteText[n.dataset.note] || 'Note info.'});
      n.addEventListener('mouseleave',()=>{asideInfo.textContent = 'Hover a slice for notes; select a mood to update the booking label.'});
    });

    // Form submission (simulate)
    document.getElementById('bookingForm').addEventListener('submit',function(e){
      e.preventDefault();
      const fd = new FormData(this);
      const payload = {};
      fd.forEach((v,k)=>payload[k]=v);
      // Basic validation message
      alert('Thanks, ' + (payload.name||'there') + '. We received your request. We will follow up to confirm a time and format.');
      this.reset();
      document.getElementById('presetPlan').value = '';
      document.querySelectorAll('#bookMood button').forEach(x=>x.classList.remove('active'));
    });
  </script>
</body>
</html>"} 
